/**
 * The puzzle archive, loaded once and served from memory.
 *
 * `data/puzzles.json` is generated by `tools/build-puzzles.ts`; this module is
 * the only thing that reads it, and it validates on load so a bad build fails
 * at startup instead of halfway through someone's run.
 *
 * Since accepted player submissions joined it there are two sources, and they
 * meet in {@link PuzzleArchive.load}. The second one is passed in rather than
 * read here: those rows live in SQLite, and an archive that had to open a
 * database to load itself could not be tested — nor built — without one, which
 * is the same argument `PastDays` makes from the other side of the same seam.
 */

import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
  byTier,
  DAILY_TIERS,
  type DailyTier,
  type DayOptions,
  dayNumber,
  nextResetAt,
  puzzleIndexForDay,
} from "../shared/daily";
import {
  BOARD_WIDTH,
  COMMUNITY_ID_BASE,
  type Puzzle,
  type PuzzlePrompt,
  toPrompt,
} from "../shared/puzzle";

/**
 * Folds `data/solutions.json` back in, when it is there.
 *
 * The answers are not in the tracked archive — a solution beside its puzzle in
 * a public repository is a published answer key — so the build writes them
 * separately and this is where the two halves meet. Absent, every puzzle still
 * loads, plays and scores; only the reveal has nothing to show, which is the
 * right way round for the thing that must not leak.
 */
function withSolutions(puzzles: Puzzle[], archivePath: string): Puzzle[] {
  const beside = join(dirname(archivePath), "solutions.json");
  if (!existsSync(beside)) return puzzles;
  const book = new Map<number, Pick<Puzzle, "solution" | "source">>(
    (JSON.parse(readFileSync(beside, "utf8")).solutions as Puzzle[]).map((entry) => [
      entry.id,
      { solution: entry.solution, source: entry.source },
    ]),
  );
  return puzzles.map((puzzle) => ({ ...puzzle, ...book.get(puzzle.id) }));
}

export interface DailyPuzzles {
  readonly day: number;
  /** One puzzle per tier: within reach, worth working at, and a wall. */
  readonly puzzles: Readonly<Record<DailyTier, Puzzle>>;
  readonly resetsAt: number;
}

const BOARD_ROW = new RegExp(`^[IJLOSTZG.]{${BOARD_WIDTH}}$`);
const PIECE_LETTERS = new Set(["I", "J", "L", "O", "S", "T", "Z"]);

/** Everything about a puzzle the engine has to be able to read. */
export type BoardShape = Pick<Puzzle, "board" | "queue" | "hold">;

/**
 * What is wrong with a board, queue and hold — or null when nothing is.
 *
 * Split out of {@link assertValid} so that the file the build writes and the
 * puzzles players submit are held to one rule rather than two that drift.
 * Everything else `assertValid` checks belongs to the archive alone: a
 * submission has no id and no target yet, because both are the server's to
 * assign and neither is the author's to claim.
 *
 * It reports the fault instead of throwing it so each caller can say it in its
 * own voice — "puzzles.json entry 12" to an operator watching a startup fail,
 * a plain sentence to a player about to lose the puzzle they just wrote.
 */
export function boardProblem(candidate: BoardShape): string | null {
  if (!Array.isArray(candidate.queue) || candidate.queue.length === 0) return "empty queue";
  if (!Array.isArray(candidate.board)) return "missing board";
  for (const row of candidate.board) {
    // The alphabet matters as much as the width: `decodeRow` casts whatever it
    // finds, so a stray character would reach the engine as an undefined mino.
    if (typeof row !== "string" || !BOARD_ROW.test(row)) {
      return `board row must be ${BOARD_WIDTH} of [IJLOSTZG.], got ${JSON.stringify(row)}`;
    }
  }
  for (const piece of candidate.queue) {
    if (!PIECE_LETTERS.has(piece)) return `queue holds ${JSON.stringify(piece)}`;
  }
  // A missing hold is a fault, not an empty one. `null` is how "nothing in
  // hold" is spelt everywhere else, and a body that simply left the field out
  // would otherwise reach the engine as undefined.
  if (candidate.hold !== null && !PIECE_LETTERS.has(candidate.hold)) {
    return `hold is ${JSON.stringify(candidate.hold)}`;
  }
  return null;
}

/**
 * One puzzle, held to the archive's rule, whichever source it came from.
 *
 * `named` rather than an index because there are two sources now and a message
 * reading "entry 4" would send an operator to the wrong one. The rule itself is
 * deliberately identical for both: an accepted submission was checked on the
 * way into the database and again at accept, so a row that fails here is a
 * database somebody edited, and the archive's own stance on that — say so at
 * startup rather than halfway through a run — is the one this file was written
 * around. Skipping the bad row instead would be quieter and worse: a day
 * already pinned to it would throw in `DaySchedule.resolve` about a puzzle
 * nothing would name, and `/api/archive/:id` would answer 404 for a puzzle
 * players hold runs against.
 */
function assertValid(puzzle: unknown, named: string): Puzzle {
  const candidate = puzzle as Puzzle;
  const problem = (detail: string) => new Error(`${named}: ${detail}`);

  if (!Number.isInteger(candidate?.id)) throw problem("missing numeric id");
  const fault = boardProblem(candidate);
  if (fault) throw problem(fault);
  if (!(candidate.targetAttack > 0)) throw problem("target attack must be positive");
  // No solution check. They live in data/solutions.json, which is untracked, so
  // a checkout without it is the ordinary case rather than a broken build.
  return candidate;
}

export class PuzzleArchive {
  private readonly byId: ReadonlyMap<number, Puzzle>;
  private readonly tiers: Readonly<Record<DailyTier, readonly Puzzle[]>>;

  private constructor(
    readonly puzzles: readonly Puzzle[],
    private readonly dayOptions: DayOptions,
  ) {
    this.byId = new Map(puzzles.map((puzzle) => [puzzle.id, puzzle]));
    // The Map is exactly why this check has to exist. It resolves a duplicate
    // id cleanly — last one wins — while both copies stay in `puzzles`, which
    // is the array the daily rotation indexes into and the rush pool is
    // filtered out of, so the same puzzle would be dealt twice under one name
    // and `runs.puzzle_id`, which has no foreign key, would merge two puzzles'
    // history with nothing anywhere to complain. Two allocators write into this
    // array now — the club's sheet and `nextCommunityPuzzleId` — and this is
    // the one place they are ever in the same list.
    if (this.byId.size !== puzzles.length) {
      // Only ever walked on the way to throwing, so the quadratic scan costs
      // nothing and reads as what it is.
      const clash = puzzles.find(
        (puzzle, index) => puzzles.findIndex((other) => other.id === puzzle.id) !== index,
      );
      throw new Error(
        `Two puzzles claim id ${clash?.id}. Club ids and the community band ` +
          `(${COMMUNITY_ID_BASE}+) must never meet; renumbering the sheet into the ` +
          "band is the way this happens.",
      );
    }
    // Partitioned once, and sorted by id inside each tier. The rotation is an
    // index into these arrays, so an order that depended on how the file
    // happened to be written would deal different puzzles after a rebuild.
    const tiers = byTier([...puzzles].sort((a, b) => a.id - b.id));
    this.tiers = tiers;
    for (const tier of DAILY_TIERS) {
      if (tiers[tier].length === 0) {
        throw new Error(`The archive has no ${tier} puzzles; a day needs one of each`);
      }
    }
  }

  /** Each tier walks its own rotation; the stream keeps them from marching together. */
  private static readonly STREAM: Readonly<Record<DailyTier, number>> = {
    easy: 1,
    medium: 2,
    hard: 3,
  };

  /**
   * The club's file plus whatever officers have accepted, as one archive.
   *
   * `community` is a third argument rather than something read in here for the
   * reason the file header gives, and it comes last so that neither of the two
   * existing call shapes had to move. The accepted puzzles carry their own
   * solutions, so {@link withSolutions} is the file's business alone — there is
   * no `data/solutions.json` entry to write for a puzzle that was never built.
   *
   * They go in *after* the file, which settles nothing about the rotation —
   * every tier is re-sorted by id in the constructor and the rush pool is
   * pinned per day — and everything about which of two puzzles sharing an id
   * the duplicate check names first.
   */
  static load(
    path: string,
    dayOptions: DayOptions = {},
    community: readonly Puzzle[] = [],
  ): PuzzleArchive {
    let parsed: { puzzles?: unknown[] };
    try {
      parsed = JSON.parse(readFileSync(path, "utf8"));
    } catch (error) {
      throw new Error(
        `Could not read ${path}. Run \`bun run puzzles\` to generate it. (${String(error)})`,
        { cause: error },
      );
    }
    const list = parsed.puzzles;
    if (!Array.isArray(list) || list.length === 0) {
      throw new Error(`${path} contains no puzzles`);
    }
    const file = withSolutions(
      list.map((entry, index) => assertValid(entry, `puzzles.json entry ${index}`)),
      path,
    );
    const accepted = community.map((puzzle) =>
      assertValid(puzzle, `accepted puzzle ${puzzle?.id}`),
    );
    return new PuzzleArchive([...file, ...accepted], dayOptions);
  }

  get(id: number): Puzzle | undefined {
    return this.byId.get(id);
  }

  /** One tier's puzzle for a day. */
  forTier(day: number, tier: DailyTier): Puzzle {
    const pool = this.tiers[tier];
    return pool[puzzleIndexForDay(day, pool.length, PuzzleArchive.STREAM[tier])]!;
  }

  /**
   * The three puzzles for a given day number, defaulting to today.
   *
   * Memoised on the day. Everything in here is constant for a calendar day and
   * four routes ask for it per request; the cost is dominated by `nextResetAt`,
   * which formats a wall clock three times through Intl.
   */
  private cached: DailyPuzzles | null = null;

  forDay(day: number = dayNumber(Date.now(), this.dayOptions)): DailyPuzzles {
    if (this.cached?.day === day) return this.cached;
    this.cached = {
      day,
      puzzles: {
        easy: this.forTier(day, "easy"),
        medium: this.forTier(day, "medium"),
        hard: this.forTier(day, "hard"),
      },
      resetsAt: nextResetAt(Date.now(), this.dayOptions),
    };
    return this.cached;
  }

  today(): DailyPuzzles {
    return this.forDay();
  }

  /** Which of a day's three a puzzle is, or null if it is not one of them. */
  tierOfDay(day: number, puzzleId: number): DailyTier | null {
    return DAILY_TIERS.find((tier) => this.forTier(day, tier).id === puzzleId) ?? null;
  }

  currentDay(): number {
    return dayNumber(Date.now(), this.dayOptions);
  }

  /**
   * When the puzzle turns over. Here beside {@link currentDay} for the same
   * reason: the club's zone was configured once, into this object, and a caller
   * that had to be handed it again to answer the other half of "what day is it"
   * is a second place for the zone to be wrong.
   */
  resetsAt(): number {
    return nextResetAt(Date.now(), this.dayOptions);
  }

  prompt(puzzle: Puzzle): PuzzlePrompt {
    return toPrompt(puzzle);
  }
}
